package com.codegym.controller;
import com.codegym.dao.*;import com.codegym.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.SQLException;
@WebServlet("/users") public class UserServlet extends HttpServlet {private IUserDAO dao;public void init(){dao=new UserDAO();}
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String a=r.getParameter("action");if(a==null)a="list";try{switch(a){case"test-without-tran"->{dao.insertUpdateWithoutTransaction();s.getWriter().println("Finished test without transaction");}case"new"->r.getRequestDispatcher("/user/create.jsp").forward(r,s);case"edit"->{r.setAttribute("user",dao.selectUser(Integer.parseInt(r.getParameter("id"))));r.getRequestDispatcher("/user/edit.jsp").forward(r,s);}case"delete"->{r.setAttribute("user",dao.selectUser(Integer.parseInt(r.getParameter("id"))));r.getRequestDispatcher("/user/delete.jsp").forward(r,s);}default->{r.setAttribute("users",dao.selectAllUsers());r.getRequestDispatcher("/user/list.jsp").forward(r,s);}}}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String a=r.getParameter("action");try{if("insert".equals(a))dao.insertUser(new User(r.getParameter("name"),r.getParameter("email"),r.getParameter("country")));else if("update".equals(a))dao.updateUser(new User(Integer.parseInt(r.getParameter("id")),r.getParameter("name"),r.getParameter("email"),r.getParameter("country")));else if("delete".equals(a))dao.deleteUser(Integer.parseInt(r.getParameter("id")));s.sendRedirect("users");}catch(SQLException e){throw new ServletException(e);}}
}
